import React, { useState } from "react";
import { useAuth } from "@/hooks/use-auth";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Sli } from "@shared/schema";
import { queryClient } from "@/lib/queryClient";
import { useLocation } from "wouter";
import { useToast } from "@/hooks/use-toast";
import NavBar from "@/components/nav-bar";
import { 
  ArrowLeft, 
  Award, 
  CheckCircle2,
  Sparkles,
  Loader2,
  MessageCircle,
  Lightbulb,
  LightbulbOff,
  RefreshCw,
  AlertCircle
} from "lucide-react";

import { 
  Card, 
  CardContent, 
  CardDescription, 
  CardHeader, 
  CardTitle,
  CardFooter
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { scrollToTop } from "@/lib/utils";

export default function SliRefinementPage() {
  const { user } = useAuth();
  const { toast } = useToast();
  const [, navigate] = useLocation();
  const [feedback, setFeedback] = useState<string>("");
  const [isSubmitting, setIsSubmitting] = useState<boolean>(false);
  const [showFeedbackForm, setShowFeedbackForm] = useState<boolean>(false);

  // Fetch user's selected SLI
  const { data: slis, isLoading: slisLoading } = useQuery<Sli[]>({
    queryKey: ["/api/user/slis"],
    queryFn: async () => {
      const res = await fetch(`/api/user/slis`);
      if (!res.ok) throw new Error("Failed to fetch SLIs");
      return res.json();
    },
    enabled: !!user,
  });

  // Function to handle refinement submission
  const handleSubmitRefinement = async () => {
    if (!slis || slis.length === 0) {
      toast({
        title: "Error",
        description: "No SLIs found to refine",
        variant: "destructive",
      });
      return;
    }

    if (!feedback.trim()) {
      toast({
        title: "Error",
        description: "Please provide feedback for refinement",
        variant: "destructive",
      });
      return;
    }

    const sli = slis[0]; // Use the first SLI since that's the most recent one

    // Ensure an SLI is selected
    if (sli.selectedSliIndex === null) {
      toast({
        title: "Error",
        description: "Please select an SLI first before refining",
        variant: "destructive",
      });
      navigate("/sli-selection");
      return;
    }

    setIsSubmitting(true);

    try {
      // Send refinement request
      const res = await fetch('/api/user/sli/refine', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          sliId: sli.id,
          feedback: feedback,
          selectedSliIndex: sli.selectedSliIndex
        }),
      });

      if (!res.ok) {
        const errorData = await res.json();
        throw new Error(errorData.message || "Failed to refine SLI");
      }

      const data = await res.json();

      // Invalidate queries to refresh data
      queryClient.invalidateQueries({ queryKey: ["/api/user/slis"] });

      // Reset UI state
      setShowFeedbackForm(false);

      toast({
        title: "Success",
        description: "Your SLI has been refined and saved",
      });
    } catch (error) {
      toast({
        title: "Error",
        description: error instanceof Error ? error.message : "Failed to refine SLI",
        variant: "destructive",
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  // Helper function to get the selected SLI statement
  const getSelectedSliStatement = (): string => {
    if (!slis || slis.length === 0 || slis[0].selectedSliIndex === null) {
      return "";
    }

    const sli = slis[0];
    const index = sli.selectedSliIndex;

    switch(index) {
      case 1:
        return sli.statement1;
      case 2:
        return sli.statement2;
      case 3:
        return sli.statement3;
      default:
        return "";
    }
  };

  // Redirect to home if no SLIs are available
  if (!slisLoading && (!slis || slis.length === 0)) {
    toast({
      title: "No SLIs Available",
      description: "You don't have any SLIs available to refine.",
    });
    navigate("/");
    return null;
  }

  return (
    <div className="min-h-screen bg-background flex flex-col">
      <NavBar />
      <main className="flex-1 max-w-5xl mx-auto px-4 sm:px-6 py-8">
        <div className="mb-6 flex items-center gap-2">
          <Button
            variant="outline"
            size="icon"
            onClick={() => {
              scrollToTop();
              navigate("/sli-selection");
            }}
            className="h-8 w-8"
          >
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <h1 className="text-2xl font-bold">Refine Your SLI</h1>
        </div>

        {slisLoading ? (
          <div className="flex-1 flex items-center justify-center">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
            <span className="ml-2">Loading your SLIs...</span>
          </div>
        ) : slis && slis.length > 0 && slis[0].selectedSliIndex !== null ? (
          <div className="space-y-8">
            {/* Show different views based on whether the SLI has been refined already */}
            {slis[0].refinedSliText && !showFeedbackForm ? (
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2">
                    <CheckCircle2 className="h-5 w-5 text-green-500" />
                    <span>Your Refined SLI</span>
                  </CardTitle>
                  <CardDescription>
                    Your SLI has been refined based on your feedback.
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  <Tabs defaultValue="refined" className="w-full">
                    <TabsList className="grid grid-cols-3 mb-4">
                      <TabsTrigger value="refined">Refined SLI</TabsTrigger>
                      <TabsTrigger value="rationale">Rationale</TabsTrigger>
                      <TabsTrigger value="guidance">Implementation</TabsTrigger>
                    </TabsList>

                    <TabsContent value="refined">
                      <div className="space-y-4">
                        <Alert className="bg-primary/5 border-primary/20">
                          <AlertTitle className="flex items-center gap-2">
                            <Sparkles className="h-4 w-4 text-primary" />
                            <span>Final SLI Statement</span>
                          </AlertTitle>
                          <AlertDescription className="mt-2 text-lg font-medium">
                            {slis[0].refinedSliText}
                          </AlertDescription>
                        </Alert>

                        <div className="text-sm text-muted-foreground mt-4">
                          <div className="flex items-start gap-2 mb-2">
                            <ArrowLeft className="h-4 w-4 mt-0.5 text-muted-foreground" />
                            <div>
                              <p className="font-medium">Original SLI:</p>
                              <p>{getSelectedSliStatement()}</p>
                            </div>
                          </div>
                        </div>
                      </div>
                    </TabsContent>

                    <TabsContent value="rationale">
                      <div className="bg-background p-4 rounded-md border">
                        <div className="flex items-center gap-2 mb-3">
                          <MessageCircle className="h-4 w-4 text-primary" />
                          <h3 className="font-medium">Refinement Rationale</h3>
                        </div>
                        <ScrollArea className="h-[300px] rounded-md">
                          <div className="p-2 whitespace-pre-line">
                            {slis[0].refinementRationale || "No rationale provided."}
                          </div>
                        </ScrollArea>
                      </div>
                    </TabsContent>

                    <TabsContent value="guidance">
                      <div className="bg-background p-4 rounded-md border">
                        <div className="flex items-center gap-2 mb-3">
                          <Lightbulb className="h-4 w-4 text-amber-500" />
                          <h3 className="font-medium">Implementation Guidance</h3>
                        </div>
                        <ScrollArea className="h-[300px] rounded-md">
                          <div className="p-2 whitespace-pre-line">
                            {slis[0].implementationGuidance || "No implementation guidance provided."}
                          </div>
                        </ScrollArea>
                      </div>
                    </TabsContent>
                  </Tabs>
                </CardContent>
                <CardFooter className="flex flex-col border-t pt-6 gap-4">
                  <div className="flex justify-between w-full">
                    <Button
                      variant="outline"
                      onClick={() => {
                        scrollToTop();
                        navigate("/");
                      }}
                    >
                      Return to Home
                    </Button>
                    <Button
                      onClick={() => {
                        scrollToTop();
                        navigate("/sli-selection");
                      }}
                    >
                      Back to SLI Selection
                    </Button>
                  </div>

                  {/* Re-refinement section */}
                  {slis[0]?.refinementCount < 3 ? (
                    <div className="pt-2 border-t border-gray-100 mt-2 w-full">
                      <div className="flex justify-between items-center">
                        <div>
                          <h4 className="text-sm font-medium">Not quite right?</h4>
                          <p className="text-xs text-muted-foreground">
                            You can refine your SLI {3 - (slis[0]?.refinementCount || 0)} more {(3 - (slis[0]?.refinementCount || 0)) === 1 ? 'time' : 'times'}.
                          </p>
                        </div>
                        <Button 
                          variant="secondary"
                          size="sm"
                          className="gap-1"
                          onClick={() => {
                            setFeedback(""); // Clear any previous feedback
                            setShowFeedbackForm(true); // Show the feedback form
                          }}
                        >
                          <RefreshCw className="h-3.5 w-3.5" />
                          Re-refine SLI
                        </Button>
                      </div>
                    </div>
                  ) : (
                    <div className="pt-2 border-t border-gray-100 mt-2 w-full">
                      <div className="flex justify-between items-center">
                        <div className="flex items-start gap-2">
                          <AlertCircle className="h-4 w-4 text-yellow-600 mt-0.5" />
                          <div>
                            <h4 className="text-sm font-medium">Maximum refinements reached</h4>
                            <p className="text-xs text-muted-foreground">
                              You've already refined this SLI the maximum number of times (3).
                            </p>
                          </div>
                        </div>
                      </div>
                    </div>
                  )}
                </CardFooter>
              </Card>
            ) : (
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2">
                    <Award className="h-5 w-5 text-primary" />
                    <span>Your Selected SLI</span>
                  </CardTitle>
                  <CardDescription>
                    Provide feedback to improve and personalize your Single Lasting Impression.
                  </CardDescription>
                </CardHeader>
                <CardContent className="space-y-6">
                  <div className="p-4 bg-primary/10 rounded-lg border border-primary/20">
                    <p className="text-lg font-medium text-secondary">
                      {getSelectedSliStatement()}
                    </p>
                  </div>

                  <div className="space-y-3">
                    <label className="block font-medium" htmlFor="feedback">
                      Provide Feedback to Improve Your SLI
                    </label>
                    <Textarea
                      id="feedback"
                      placeholder="Describe how you'd like to refine your SLI. For example: Make it more concise, emphasize a specific quality, adjust the tone to be more approachable, etc."
                      rows={5}
                      value={feedback}
                      onChange={(e) => setFeedback(e.target.value)}
                      className="w-full"
                    />
                  </div>

                  <div className="flex justify-between mt-8">
                    {showFeedbackForm && slis[0].refinedSliText ? (
                      <Button
                        variant="outline"
                        onClick={() => {
                          setShowFeedbackForm(false); // Go back to viewing the refined SLI
                        }}
                      >
                        Cancel
                      </Button>
                    ) : (
                      <Button
                        variant="outline"
                        onClick={() => {
                          scrollToTop();
                          navigate("/sli-selection");
                        }}
                      >
                        Back
                      </Button>
                    )}
                    <Button
                      onClick={handleSubmitRefinement}
                      disabled={isSubmitting}
                      className="gap-2"
                    >
                      {isSubmitting ? (
                        <>
                          <Loader2 className="h-4 w-4 animate-spin" />
                          Processing...
                        </>
                      ) : (
                        <>
                          <Sparkles className="h-4 w-4" />
                          {showFeedbackForm && slis[0].refinedSliText ? "Re-refine My SLI" : "Refine My SLI"}
                        </>
                      )}
                    </Button>
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        ) : (
          <Card>
            <CardContent className="p-6">
              <div className="text-center">
                <div className="mx-auto flex h-12 w-12 items-center justify-center rounded-full bg-primary/10">
                  <Award className="h-6 w-6 text-primary" />
                </div>
                <h3 className="mt-3 text-lg font-medium">No SLI Selected</h3>
                <p className="mt-2 text-sm text-gray-500">
                  You need to select an SLI before you can refine it.
                </p>
                <Button
                  className="mt-4"
                  onClick={() => {
                    scrollToTop();
                    navigate("/sli-selection");
                  }}
                >
                  Select an SLI
                </Button>
              </div>
            </CardContent>
          </Card>
        )}
      </main>
    </div>
  );
}

client/src/components/profile-form/profi.content:
import { useState, KeyboardEvent } from "react";
import { UserProfile, InsertSkill, InsertLanguage } from "@shared/schema";
import { useToast } from "@/hooks/use-toast";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Loader2, X } from "lucide-react";
import { apiRequest, queryClient } from "@/lib/queryClient";

interface ProfileStep3Props {
  userProfile?: UserProfile;
  onBack: () => void;
  onComplete: () => void;
}

export default function ProfileStep3({
  userProfile,
  onBack,
  onComplete,
}: ProfileStep3Props) {
  const { toast } = useToast();

  const [skillInput, setSkillInput] = useState("");
  const [selectedLanguage, setSelectedLanguage] = useState("");
  const [selectedProficiency, setSelectedProficiency] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Add a skill to the user's profile
  const handleAddSkill = async () => {
    if (!skillInput.trim()) return;

    try {
      await apiRequest("POST", "/api/skills", { name: skillInput.trim() });

      // Clear input and refresh data
      setSkillInput("");
      queryClient.invalidateQueries({ queryKey: ["/api/user/profile"] });

      toast({
        title: "Success",
        description: "Skill added successfully",
      });
    } catch (error) {
      toast({
        title: "Error",
        description: "Failed to add skill",
        variant: "destructive",
      });
    }
  };

  // Delete a skill
  const handleDeleteSkill = async (id: number) => {
    try {
      await apiRequest("DELETE", `/api/skills/${id}`);

      // Refresh data
      queryClient.invalidateQueries({ queryKey: ["/api/user/profile"] });

      toast({
        title: "Success",
        description: "Skill removed successfully",
      });
    } catch (error) {
      toast({
        title: "Error",
        description: "Failed to remove skill",
        variant: "destructive",
      });
    }
  };

  // Add a language to the user's profile
  const handleAddLanguage = async () => {
    if (!selectedLanguage || !selectedProficiency) {
      toast({
        title: "Error",
        description: "Please select both a language and proficiency level",
        variant: "destructive",
      });
      return;
    }

    try {
      await apiRequest("POST", "/api/languages", {
        name: selectedLanguage,
        proficiency: selectedProficiency,
      });

      // Clear inputs and refresh data
      setSelectedLanguage("");
      setSelectedProficiency("");
      queryClient.invalidateQueries({ queryKey: ["/api/user/profile"] });

      toast({
        title: "Success",
        description: "Language added successfully",
      });
    } catch (error) {
      toast({
        title: "Error",
        description: "Failed to add language",
        variant: "destructive",
      });
    }
  };

  // Delete a language
  const handleDeleteLanguage = async (id: number) => {
    try {
      await apiRequest("DELETE", `/api/languages/${id}`);

      // Refresh data
      queryClient.invalidateQueries({ queryKey: ["/api/user/profile"] });

      toast({
        title: "Success",
        description: "Language removed successfully",
      });
    } catch (error) {
      toast({
        title: "Error",
        description: "Failed to remove language",
        variant: "destructive",
      });
    }
  };

  // Handle enter key press in skill input
  const handleSkillKeyPress = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleAddSkill();
    }
  };

  // Complete the profile setup
  const handleCompleteProfile = async () => {
    setIsSubmitting(true);
    try {
      await onComplete();
    } catch (error) {
      toast({
        title: "Error",
        description: "Failed to complete profile",
        variant: "destructive",
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="p-6">
      <div className="grid grid-cols-1 gap-6">
        {/* Skills Section */}
        <div>
          <label htmlFor="skills" className="block text-sm font-medium text-[#333333] mb-1">Skills</label>
          <div className="relative">
            <Input
              id="skillInput"
              value={skillInput}
              onChange={(e) => setSkillInput(e.target.value)}
              onKeyPress={handleSkillKeyPress}
              className="block w-full px-4 py-3 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#bed6d1] focus:ring-opacity-50"
              placeholder="Add a skill (e.g. JavaScript, Project Management)"
            />
            <Button
              type="button"
              onClick={handleAddSkill}
              className="absolute inset-y-0 right-0 px-4 flex items-center bg-[#bed6d1] text-white rounded-r-md hover:bg-opacity-90 focus:outline-none"
            >
              Add
            </Button>
          </div>

          <div className="mt-3 flex flex-wrap gap-2" id="skillsList">
            {userProfile?.skills && userProfile.skills.length > 0 ? (
              userProfile.skills.map((skill) => (
                <div
                  key={skill.id}
                  className="inline-flex items-center px-3 py-1 rounded-full text-sm bg-[#dcede9] bg-opacity-20 text-[#bed6d1]"
                >
                  <span>{skill.name}</span>
                  <button
                    type="button"
                    className="ml-1 text-[#bed6d1] focus:outline-none"
                    onClick={() => handleDeleteSkill(skill.id)}
                  >
                    <X className="h-4 w-4" />
                  </button>
                </div>
              ))
            ) : (
              <p className="text-gray-500">No skills added yet.</p>
            )}
          </div>
        </div>

        {/* Languages Section */}
        <div>
          <label htmlFor="languages" className="block text-sm font-medium text-[#333333] mb-1">Languages</label>
          <Select value={selectedLanguage} onValueChange={setSelectedLanguage}>
            <SelectTrigger className="w-full mb-2">
              <SelectValue placeholder="Select a language" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="english">English</SelectItem>
              <SelectItem value="spanish">Spanish</SelectItem>
              <SelectItem value="french">French</SelectItem>
              <SelectItem value="german">German</SelectItem>
              <SelectItem value="chinese">Chinese</SelectItem>
              <SelectItem value="japanese">Japanese</SelectItem>
              <SelectItem value="arabic">Arabic</SelectItem>
              <SelectItem value="russian">Russian</SelectItem>
              <SelectItem value="portuguese">Portuguese</SelectItem>
              <SelectItem value="italian">Italian</SelectItem>
              <SelectItem value="hindi">Hindi</SelectItem>
              <SelectItem value="korean">Korean</SelectItem>
              <SelectItem value="other">Other</SelectItem>
            </SelectContent>
          </Select>

          <Select value={selectedProficiency} onValueChange={setSelectedProficiency}>
            <SelectTrigger className="w-full mb-2">
              <SelectValue placeholder="Select proficiency level" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="Native or bilingual">Native or bilingual</SelectItem>
              <SelectItem value="Fluent">Fluent</SelectItem>
              <SelectItem value="Advanced">Advanced</SelectItem>
              <SelectItem value="Intermediate">Intermediate</SelectItem>
              <SelectItem value="Basic">Basic</SelectItem>
            </SelectContent>
          </Select>

          <Button
            type="button"
            variant="outline"
            className="mt-2 px-4 py-2 border border-[#bed6d1] text-[#bed6d1] rounded-md hover:bg-[#bed6d1] hover:bg-opacity-10 focus:outline-none"
            onClick={handleAddLanguage}
          >
            Add Language
          </Button>

          <div className="mt-3">
            <ul className="divide-y divide-gray-200" id="languagesList">
              {userProfile?.languages && userProfile.languages.length > 0 ? (
                userProfile.languages.map((language) => (
                  <li key={language.id} className="py-2 flex justify-between items-center">
                    <div>
                      <span className="font-medium">{language.name}</span>
                      <span className="text-sm text-gray-500 ml-2">{language.proficiency}</span>
                    </div>
                    <button
                      type="button"
                      className="text-[#E34240] hover:text-opacity-80 focus:outline-none"
                      onClick={() => handleDeleteLanguage(language.id)}
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M9 2a1 1 0 00-.894.553L7.382 4H4a1 1 0 000 2v10a2 2 0 002 2h8a2 2 0 002-2V6a1 1 0 100-2h-3.382l-.724-1.447A1 1 0 0011 2H9zM7 8a1 1 0 012 0v6a1 1 0 11-2 0V8zm5-1a1 1 0 00-1 1v6a1 1 0 102 0V8a1 1 0 00-1-1z" clipRule="evenodd" />
                      </svg>
                    </button>
                  </li>
                ))
              ) : (
                <li className="py-2 text-gray-500">No languages added yet.</li>
              )}
            </ul>
          </div>
        </div>
      </div>

      <div className="mt-8 flex justify-between">
        <Button
          type="button"
          variant="outline"
          className="px-6 py-3 border border-gray-300 rounded-md text-[#333333] hover:bg-gray-50"
          onClick={onBack}
        >
          Back
        </Button>
        <Button
          type="button"
          className="px-6 py-3 bg-[#bed6d1] hover:bg-opacity-90 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#bed6d1]"
          onClick={handleCompleteProfile}
          disabled={isSubmitting}
        >
          {isSubmitting ? (
            <>
              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              Completing...
            </>
          ) : (
            "Complete Profile"
          )}
        </Button>
      </div>
    </div>
  );
}

