import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export function formatDate(date: Date) {
  return new Intl.DateTimeFormat("en-US", {
    month: "long",
    day: "numeric",
    year: "numeric",
  }).format(date);
}

// Scroll to top function for navigation
export function scrollToTop() {
  window.scrollTo({
    top: 0,
    behavior: "smooth",
  });
}

// Function to capitalize the first letter of each word
export function capitalizeWords(str: string) {
  return str
    .toLowerCase()
    .split(" ")
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
}

// Function to truncate a string to a specified length with ellipsis
export function truncateString(str: string, maxLength: number) {
  if (str.length <= maxLength) return str;
  return str.slice(0, maxLength) + "...";
}

// Function to generate a random color (could be used for avatars, etc.)
export function getRandomColor() {
  const letters = "0123456789ABCDEF";
  let color = "#";
  for (let i = 0; i < 6; i++) {
    color += letters[Math.floor(Math.random() * 16)];
  }
  return color;
}

// Function to generate an initial from a name (for avatars)
export function getInitials(name: string) {
  if (!name) return "?";
  const parts = name.split(" ");
  if (parts.length === 1) return parts[0].charAt(0).toUpperCase();
  return (parts[0].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase();
}

// Function to format a number with commas
export function formatNumber(num: number) {
  return num.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

// Function to calculate a reading time
export function readingTime(text: string, wordsPerMinute = 200) {
  const words = text.trim().split(/\s+/).length;
  const time = Math.ceil(words / wordsPerMinute);
  return time;
}

server/email-service.ts.content:
import { MailService } from '@sendgrid/mail';
import mail from '@sendgrid/mail';

if (!process.env.SENDGRID_API_KEY) {
  console.warn("SENDGRID_API_KEY environment variable is not set. Email functionality will not work.");
}

// Initialize SendGrid with the API key
mail.setApiKey(process.env.SENDGRID_API_KEY || '');

interface EmailParams {
  to: string;
  from: string;
  subject: string;
  text?: string;
  html?: string;
}

/**
 * Sends an email using the SendGrid API
 * @param params Email parameters
 * @returns true if the email was sent successfully, false otherwise
 */
export async function sendEmail(params: EmailParams): Promise<boolean> {
  try {
    const msg = {
      to: params.to,
      from: params.from, // This needs to be a verified sender in SendGrid
      subject: params.subject,
      text: params.text || '',
      html: params.html || ''
    };

    console.log(`Attempting to send email to: ${params.to} from: ${params.from}`);
    await mail.send(msg);
    console.log(`Email sent successfully to ${params.to}`);
    return true;
  } catch (error: any) {
    console.error('SendGrid email error:', error);

    // Log detailed error information
    if (error.response) {
      console.error('Error details:', {
        status: error.code,
        body: error.response.body,
      });
    }

    return false;
  }
}

/**
 * Sends a password reset email to the user
 * @param to The recipient's email address
 * @param resetToken The password reset token
 * @param baseUrl The base URL of the application (for building the reset link)
 * @returns true if the email was sent successfully, false otherwise
 */
export async function sendPasswordResetEmail(
  to: string,
  resetToken: string,
  baseUrl: string
): Promise<boolean> {
  // For SendGrid, the sender must be a verified domain or email
  // In production, replace this with your actual verified sender email
  const from = 'notifications@slipro.com'; // Replace with your verified sender email';
  const subject = 'Password Reset Request';

  // Get base URL from request or environment
  const resetUrl = `${baseUrl}/reset-password?token=${resetToken}`;

  const text = `
    You have requested to reset your password.

    Please click on the following link to reset your password:
    ${resetUrl}

    If you did not request this, please ignore this email and your password will remain unchanged.

    This link will expire in 1 hour.
  `;

  const html = `
    <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
      <h2 style="color: #4A5568; text-align: center;">Password Reset Request</h2>
      <p>You have requested to reset your password.</p>
      <div style="text-align: center; margin: 30px 0;">
        <a href="${resetUrl}" style="background-color: #bed6d1; color: white; padding: 12px 24px; text-decoration: none; border-radius: 4px; display: inline-block; font-weight: bold;">
          Reset Your Password
        </a>
      </div>
      <p>If you did not request this, please ignore this email and your password will remain unchanged.</p>
      <p style="color: #718096; font-size: 14px;">This link will expire in 1 hour.</p>
    </div>
  `;

  return await sendEmail({
    to,
    from,
    subject,
    text,
    html
  });
}

