          <div className="mb-6">
            <h3 className="text-lg font-semibold text-gray-900 mb-3">
              Optional Documents
            </h3>
            <div className="mb-4">
              <p className="text-sm text-gray-700 mb-3">
                <strong>Professional/Personality Assessments (Optional)</strong>
                <br />
                If you have completed any personality, strengths, or leadership
                assessments, please share them. These provide valuable insights
                into your natural positioning and communication style.
              </p>

              <div className="mb-4">
                <p className="text-sm font-medium text-gray-900 mb-2">
                  Common Assessment Types:
                </p>
                <ul className="text-sm text-gray-700 space-y-1 ml-4 list-disc">
                  <li>Myers-Briggs Type Indicator (MBTI)</li>
                  <li>Enneagram</li>
                  <li>StrengthsFinder / CliftonStrengths</li>
                  <li>VIA Character Strengths Survey</li>
                  <li>DiSC Profile</li>
                  <li>360° Leadership or Team Assessments</li>
                  <li>Any other professional assessment results</li>
                </ul>
              </div>

              <div className="p-3 bg-blue-50 rounded-lg border border-blue-200">
                <p className="text-sm text-gray-700">
                  <strong>Why share these?</strong>
                  <br />
                  Personality and strengths assessments help us understand your
                  natural communication style and authentic professional
                  positioning, making your SLI more genuine and sustainable.
                </p>
              </div>
            </div>
          </div>

          <form onSubmit={handleUpload} className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="name">Document Name</Label>
              <Input
                id="name"
                placeholder="e.g., MBTI Assessment Results"
                value={name}
                onChange={(e) => setName(e.target.value)}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="type">Document Type</Label>
              <Select value={type} onValueChange={setType}>
                <SelectTrigger>
                  <SelectValue placeholder="Select document type" />
                </SelectTrigger>
                <SelectContent>
                  {DOCUMENT_TYPES.map((docType) => (
                    <SelectItem key={docType.id} value={docType.id}>
                      {docType.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="file">Assessment File</Label>
              <Input
