                type="file"
                accept="application/pdf,.doc,.docx"
                ref={fileInputRef}
                className="cursor-pointer"
              />
              <p className="text-xs text-gray-500">
                <strong>Accepted formats:</strong> PDF, DOC & DOCX • Max file
                size: 2MB
              </p>
            </div>

            <Button type="submit" className="w-full" disabled={isUploading}>
              {isUploading ? (
                <>Uploading...</>
              ) : (
                <>
                  <Upload className="mr-2 h-4 w-4" />
                  Upload Assessment
                </>
              )}
            </Button>
          </form>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>My Documents</CardTitle>
          <CardDescription>
            View and manage your uploaded documents
          </CardDescription>
        </CardHeader>
        <CardContent>
          {isLoadingDocuments ? (
            <div className="py-4 text-center text-gray-500">
              Loading documents...
            </div>
          ) : documents.length === 0 ? (
            <div className="py-4 text-center text-gray-500">
              <FileText className="mx-auto h-12 w-12 opacity-20 mb-2" />
              <p>No documents uploaded yet</p>
            </div>
          ) : (
            <div>
              {/* Group documents by type */}
              {(() => {
                // Separate user-uploaded documents from assessment documents
                const userDocuments = documents.filter(
                  (doc) => !doc.type.startsWith("assessment-"),
                );

                const assessmentDocuments = documents.filter((doc) =>
                  doc.type.startsWith("assessment-"),
                );

                return (
                  <>
                    {/* Regular Documents Section */}
                    {userDocuments.length > 0 && (
                      <div className="mb-6">
                        <h3 className="text-md font-medium mb-3 text-gray-700">
                          Professional Documents
                        </h3>
                        <div className="space-y-4">
                          {userDocuments.map((document) => {
                            // Find document type label
                            const docType =
                              DOCUMENT_TYPES.find((t) => t.id === document.type)
                                ?.label || document.type;

                            return (
                              <div
                                key={document.id}
                                className="flex items-center justify-between border p-3 rounded-md"
                              >
                                <div className="flex items-center space-x-3">
                                  {document.type === "resume" ? (
                                    <FileText className="h-8 w-8 text-[#bed6d1]" />
                                  ) : document.type === "linkedin" ? (
                                    <FileText className="h-8 w-8 text-[#bed6d1]" />
                                  ) : (
                                    <File className="h-8 w-8 text-[#bed6d1]" />
                                  )}
                                  <div>
                                    <h4 className="font-medium">
                                      {document.name}
                                    </h4>
                                    <p className="text-sm text-gray-500">
                                      {docType}
                                    </p>
                                  </div>
                                </div>

                                <div className="flex space-x-2">
                                  <Button
                                    variant="outline"
                                    size="sm"
                                    onClick={() => handleViewDocument(document)}
                                  >
                                    <Eye className="h-4 w-4" />
                                  </Button>
                                  <Button
                                    variant="outline"
                                    size="sm"
                                    className="text-red-500"
                                    onClick={() => handleDelete(document.id)}
                                  >
                                    <Trash2 className="h-4 w-4" />
                                  </Button>
                                </div>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    )}

                    {/* Assessment Documents Section */}
                    {assessmentDocuments.length > 0 && (
                      <div>
                        <h3 className="text-md font-medium mb-3 text-gray-700">
                          Assessment Documents
                        </h3>
                        <div className="space-y-4">
                          {assessmentDocuments.map((document) => {
                            // Extract assessment type
                            let docType = "Assessment";
                            if (document.type === "assessment-pdf") {
                              docType = "Assessment (PDF)";
                            } else if (document.type === "assessment-image") {
                              docType = "Assessment (Image)";
                            } else if (document.type === "assessment-doc") {
                              docType = "Assessment (Document)";
                            }

                            return (
                              <div
                                key={document.id}
                                className="flex items-center justify-between border border-[#dcede9] bg-[#f5faf9] p-3 rounded-md"
                              >
                                <div className="flex items-center space-x-3">
                                  {document.type === "assessment-pdf" ? (
                                    <FileText className="h-8 w-8 text-[#bed6d1]" />
                                  ) : document.type === "assessment-image" ? (
                                    <Image className="h-8 w-8 text-[#bed6d1]" />
                                  ) : document.type === "assessment-doc" ? (
                                    <FileType className="h-8 w-8 text-[#bed6d1]" />
                                  ) : (
                                    <File className="h-8 w-8 text-[#bed6d1]" />
                                  )}
                                  <div>
                                    <h4 className="font-medium">
                                      {document.name}
                                    </h4>
                                    <p className="text-sm text-gray-500">
                                      {docType}
                                    </p>
                                  </div>
                                </div>

                                <div className="flex space-x-2">
                                  <Button
                                    variant="outline"
                                    size="sm"
                                    onClick={() => handleViewDocument(document)}
                                  >
                                    {document.type === "assessment-image" ? (
                                      <Image className="h-4 w-4" />
                                    ) : (
                                      <Eye className="h-4 w-4" />
                                    )}
                                  </Button>
                                  <Button
                                    variant="outline"
                                    size="sm"
                                    className="text-red-500"
                                    onClick={() => handleDelete(document.id)}
                                  >
                                    <Trash2 className="h-4 w-4" />
                                  </Button>
                                </div>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    )}
                  </>
                );
              })()}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Page Footer */}
      <div className="mt-8 p-6 bg-gray-50 rounded-lg border">
        <div className="space-y-3 text-sm text-gray-600">
          <p>
            <strong>Having trouble with uploads?</strong> Contact support at{" "}
            <a
              href="mailto:support@slipro.com"
              className="text-blue-600 hover:text-blue-800 underline"
            >
              support@slipro.com
            </a>{" "}
            or use the chat feature for assistance.
          </p>
          <p>
            <strong>Privacy Note:</strong> All documents are securely stored and
            only used to develop your personalized SLI strategy. Documents are
            not shared with third parties.
          </p>
        </div>
      </div>
    </div>
  );
};

export default DocumentUpload;

