          ? "assessment-pdf"
          : file.name.toLowerCase().match(/\.(jpg|jpeg|png)$/)
            ? "assessment-image"
            : "assessment-doc";

        await apiRequest("POST", "/api/documents", {
          name: `Assessment: ${file.name}`,
          type: fileType,
          fileName: file.name,
          fileData: fileData,
        });
      }

      toast({
        title: "Files Uploaded",
        description: `Successfully uploaded ${files.length} file${files.length > 1 ? "s" : ""}.`,
      });
