    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader2 className="h-8 w-8 animate-spin text-[#bed6d1]" />
      </div>
    );
  }

  return (
    <div className="bg-gray-50 min-h-screen">
      <div className="container py-10 px-4 sm:px-6 lg:px-8 max-w-5xl mx-auto">
        <Card className="border-none shadow-md">
          <CardHeader className="bg-[#202436] text-white rounded-t-lg">
            <div className="flex justify-between items-center">
              <div>
                <CardTitle className="text-2xl font-bold">
                  Branding Assessment: Build Your Professional Foundation
                  {userProfile?.questionnaire?.isDraft && (
                    <span className="ml-2 inline-flex items-center rounded-md bg-yellow-100 px-2 py-1 text-xs font-medium text-yellow-800 ring-1 ring-inset ring-yellow-600/20">
                      Draft
                    </span>
                  )}
                </CardTitle>
                <CardDescription className="text-white opacity-90">
                  {userProfile?.questionnaire
                    ? "Review or update your career insights to receive personalized guidance."
                    : "This questionnaire helps us understand your unique experience, aspirations, and digital presence. Your responses will guide the development of your Single Lasting Impression (SLI) and personalized content strategy. Complete each section thoughtfully—this is the first step toward taking control of how you're perceived professionally."}
                </CardDescription>
              </div>
              <Button
                variant="outline"
                className="bg-[#202436] text-[#6c8083] hover:bg-gray-100 hover:text-[#4c5c5e]"
                onClick={(e) => {
                  e.preventDefault();

                  // No longer auto-saving when leaving the page per user request

                  // Just navigate back to home with replace to clear navigation history
                  navigate("/", { replace: true });
                }}
              >
                Back to Home
              </Button>
            </div>
          </CardHeader>
          <CardContent className="p-6 lg:p-8">
            {/* Progress indicator */}
            <div className="mb-8">
              <div className="flex items-center justify-between">
                {Array.from({ length: totalSteps }).map((_, index) => (
                  <div key={index} className="flex flex-col items-center">
                    <div
                      onClick={(e) => {
                        navigateToStep(index);
                      }}
                      className={`w-10 h-10 rounded-full flex items-center justify-center mb-2 ${
                        index + 1 === currentStep
                          ? "bg-[#bed6d1] text-white"
                          : index + 1 < currentStep
                            ? "bg-green-500 text-white"
                            : "bg-gray-200 text-gray-500"
                      }`}
                    >
                      {index + 1 < currentStep ? (
                        <CheckCircle className="h-5 w-5" />
                      ) : (
                        index + 1
                      )}
                    </div>
                    <span className="text-xs text-gray-500">
                      {index === 0
                        ? "Industry"
                        : index === 1
                          ? "Digital Presence"
                          : index === 2
                            ? "Branding & Content"
                            : index === 3
                              ? "Interests"
                              : "Professional Goals"}
                    </span>
                  </div>
                ))}
              </div>
              <div className="mt-2 h-1 bg-gray-200 w-full rounded-full overflow-hidden">
                <div
                  className="h-full bg-[#bed6d1] transition-all duration-300 ease-in-out"
                  style={{ width: `${(currentStep / totalSteps) * 100}%` }}
                ></div>
              </div>
            </div>

            <div className="space-y-6">
              {renderStepContent()}

              <div className="flex justify-between mt-8">
                <Button
                  type="button"
                  variant="outline"
                  onClick={prevStep}
                  disabled={isFirstStep}
                  className="w-[120px]"
                >
                  Previous
                </Button>

                <div className="flex items-center gap-2">
                  {/* Auto-save indicator */}
                  {saveStatus === "saving" && (
                    <div className="text-xs text-muted-foreground flex items-center mr-2">
                      <Loader2 className="h-3 w-3 animate-spin mr-1" />
                      Saving...
                    </div>
                  )}
                  {saveStatus === "saved" && (
                    <div className="text-xs text-green-600 flex items-center mr-2">
                      <CheckCircle className="h-3 w-3 mr-1" />
                      Saved
                    </div>
                  )}

                  {/* Save as Draft button - only shown if questionnaire doesn't exist or is a draft */}
                  {(!userProfile?.questionnaire ||
                    userProfile?.questionnaire?.isDraft) && (
                    <Button
                      type="button"
                      onClick={handleSaveAsDraft}
                      className="w-[120px]"
                      variant="outline"
                      disabled={saveAsDraftMutation.isPending}
                    >
                      {saveAsDraftMutation.isPending ? (
                        <Loader2 className="h-4 w-4 animate-spin mr-2" />
                      ) : null}
                      Save Progress
                    </Button>
                  )}

                  {/* Submit or Next button */}
                  {isLastStep ? (
                    <Button
                      type="button"
                      onClick={handleSubmit}
                      className="w-[120px] bg-[#bed6d1] hover:bg-[#6c8083]"
                      disabled={questionnaireMutation.isPending}
                    >
                      {questionnaireMutation.isPending ? (
                        <Loader2 className="h-4 w-4 animate-spin mr-2" />
                      ) : null}
                      Submit
                    </Button>
                  ) : (
                    <Button
                      type="button"
                      onClick={nextStep}
                      className="w-[120px] bg-[#bed6d1] hover:bg-[#6c8083]"
                    >
                      Next
                    </Button>
                  )}
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

