                                    checked={field.value === option.value}
                                    onChange={() => field.onChange(option.value)}
                                    className="mt-0.5 accent-[#bed6d1] shrink-0"
                                  />
                                  <span className="text-[13px] text-[#303454] leading-snug group-hover:text-[#6c8083] transition-colors">
