import { ReactNode } from "react";
import { useAuth } from "@/hooks/use-auth";
import { useLocation } from "wouter";
import { 
  BarChart, 
  Users, 
  LogOut, 
  Home,
  Menu,
  X
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { Sheet, SheetContent, SheetTrigger } from "@/components/ui/sheet";
import { cn } from "@/lib/utils";

interface AdminLayoutProps {
  children: ReactNode;
}

export default function AdminLayout({ children }: AdminLayoutProps) {
  const { user, logoutMutation } = useAuth();
  const [location, navigate] = useLocation();

  const isActive = (path: string) => {
    return location.startsWith(path);
  };

  const handleLogout = async () => {
    await logoutMutation.mutateAsync();
    navigate("/admin/login");
  };

  const navItems = [
    {
      title: "Dashboard",
      icon: BarChart,
      href: "/admin/dashboard",
      active: isActive("/admin/dashboard"),
    },
    {
      title: "Users",
      icon: Users,
      href: "/admin/users",
      active: isActive("/admin/users"),
    },
  ];

  const NavLink = ({
    href,
    icon: Icon,
    title,
    active,
    isMobile = false,
  }: {
    href: string;
    icon: typeof Home;
    title: string;
    active: boolean;
    isMobile?: boolean;
  }) => (
    <Button
      variant="ghost"
      className={cn(
        "w-full justify-start",
        active ? "bg-accent text-accent-foreground" : "hover:bg-accent/50",
        isMobile ? "mb-1" : ""
      )}
      onClick={() => navigate(href)}
    >
      <Icon className="mr-2 h-4 w-4" />
      {title}
    </Button>
  );

  const SidebarContent = ({ isMobile = false }: { isMobile?: boolean }) => (
    <div className={cn("space-y-4", isMobile ? "py-6" : "")}>
      <div className="px-3 py-2">
        <h2 className="px-4 text-lg font-semibold tracking-tight">
          SLI Pro Admin
        </h2>
        <p className="px-4 text-sm text-muted-foreground">
          {user?.firstName} {user?.lastName}
        </p>
      </div>
      <Separator />
      <div className="px-3 py-2">
        {navItems.map((item) => (
          <NavLink
            key={item.href}
            href={item.href}
            icon={item.icon}
            title={item.title}
            active={item.active}
            isMobile={isMobile}
          />
        ))}
      </div>
      <Separator />
      <div className="px-3 py-2">
        <Button
          variant="ghost"
          className="w-full justify-start hover:bg-accent/50"
          onClick={handleLogout}
          disabled={logoutMutation.isPending}
        >
          <LogOut className="mr-2 h-4 w-4" />
          Logout
          {logoutMutation.isPending && (
            <span className="ml-2 inline-block h-4 w-4 animate-spin rounded-full border-2 border-current border-t-transparent" />
          )}
        </Button>
      </div>
    </div>
  );

  return (
    <div className="flex min-h-screen bg-background">
      {/* Desktop Sidebar */}
      <aside className="hidden w-64 border-r bg-card lg:block">
        <SidebarContent />
      </aside>

      {/* Mobile Sidebar */}
