client/src/components/dashboard/SessionC.content:
import { Lock, Play, MessageSquare, CheckCircle } from "lucide-react";

type SessionStatus = "locked" | "available" | "in_progress" | "completed";

interface SessionCardProps {
  header: string;
  title: string;
  description: string;
  status: SessionStatus;
  onClick?: () => void;
}

const statusConfig: Record<SessionStatus, {
  icon: typeof Lock;
  label: string;
  labelClass: string;
}> = {
  locked: {
    icon: Lock,
    label: "Locked",
    labelClass: "text-gray-400",
  },
  available: {
    icon: Play,
    label: "Available",
    labelClass: "text-[var(--dashboard-aqua)]",
  },
  in_progress: {
    icon: MessageSquare,
    label: "In Progress",
    labelClass: "text-amber-500",
  },
  completed: {
    icon: CheckCircle,
    label: "Completed",
    labelClass: "text-emerald-500",
  },
};

export default function SessionCard({
  header,
  title,
  description,
  status,
  onClick,
}: SessionCardProps) {
  const config = statusConfig[status];
  const Icon = config.icon;
  const isClickable = status !== "locked";

  return (
    <div
      onClick={() => isClickable && onClick?.()}
      className={`bg-white p-8 shadow-[0_20px_50px_rgba(0,0,0,0.03)] border border-[var(--dashboard-border)] flex flex-col transition-all duration-300 ${
        isClickable
          ? "cursor-pointer hover:shadow-[0_20px_50px_rgba(0,0,0,0.08)] hover:-translate-y-0.5"
          : "opacity-50 cursor-not-allowed"
      }`}
    >
      <div className="flex items-center justify-between mb-4">
        <span className="text-[10px] uppercase tracking-[2px] text-[var(--dashboard-aqua)] font-semibold">
          {header}
        </span>
        <div className={`flex items-center gap-1.5 text-[10px] uppercase tracking-[1px] font-semibold ${config.labelClass}`}>
          <Icon className="w-3.5 h-3.5" />
          {config.label}
        </div>
      </div>

      <h3 className="dashboard-heading text-xl font-normal mb-3 text-[var(--dashboard-void)]">
        {title}
      </h3>

      <p className="text-sm leading-relaxed text-gray-500 flex-1">
        {description}
      </p>
    </div>
  );
}

client/src/assets/css/intake-theme.css.content:
:root {
  --intake-void: #202436;
  --intake-silk: #f8f9fa;
  --intake-aqua: #bed6d1;
  --intake-aqua-dark: #6c8083;
  --intake-sand: #b3b19c;
  --intake-border: #e6e8eb;
  --intake-aqua-light: #e8f0ee;
  --intake-void-light: #2d3352;
  --intake-gradient-start: #202436;
  --intake-gradient-end: #2d3352;
}

.intake-layout {
  font-family: 'Montserrat', sans-serif;
  -webkit-font-smoothing: antialiased;
}

.intake-heading {
  font-family: 'Lora', 'Charter', 'Georgia', serif;
}

.intake-page {
  background: linear-gradient(135deg, var(--intake-silk) 0%, #eef2f1 50%, #f0ede8 100%);
}

.intake-header {
  background: linear-gradient(135deg, var(--intake-void) 0%, var(--intake-void-light) 100%);
  border-radius: 16px;
  padding: 32px;
  margin-bottom: 32px;
  position: relative;
  overflow: hidden;
}

.intake-header::before {
  content: '';
  position: absolute;
  top: -40%;
  right: -10%;
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, var(--intake-aqua) 0%, transparent 70%);
  opacity: 0.08;
  border-radius: 50%;
}

.intake-header::after {
  content: '';
  position: absolute;
  bottom: -30%;
  left: 10%;
  width: 200px;
  height: 200px;
  background: radial-gradient(circle, var(--intake-sand) 0%, transparent 70%);
  opacity: 0.06;
  border-radius: 50%;
}

.intake-progress-track {
  background: rgba(255, 255, 255, 0.15);
  border-radius: 999px;
  height: 6px;
  overflow: hidden;
}

.intake-progress-fill {
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--intake-aqua) 0%, #a8ccc5 100%);
  transition: width 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}

.intake-section {
  background: white;
  border-radius: 14px;
  border: 1px solid var(--intake-border);
  padding: 28px;
  transition: box-shadow 0.2s ease, border-color 0.2s ease;
}

.intake-section:hover {
  box-shadow: 0 2px 12px rgba(32, 36, 54, 0.06);
  border-color: var(--intake-aqua);
}

.intake-info-block {
  background: linear-gradient(135deg, var(--intake-aqua-light) 0%, #f4f6f5 100%);
  border-radius: 14px;
  border: 1px solid var(--intake-aqua);
  border-left: 4px solid var(--intake-aqua);
  padding: 24px 28px;
}

.intake-privacy-block {
  background: linear-gradient(135deg, var(--intake-aqua-light) 0%, #f0f5f4 100%);
  border-radius: 14px;
  border: 1px solid var(--intake-aqua);
  padding: 28px;
}

.intake-btn-primary {
  background: linear-gradient(135deg, var(--intake-void) 0%, var(--intake-void-light) 100%);
  color: white;
  border: none;
  padding: 12px 28px;
  border-radius: 10px;
  font-weight: 600;
  font-size: 14px;
  letter-spacing: 0.3px;
  transition: all 0.25s ease;
  box-shadow: 0 2px 8px rgba(32, 36, 54, 0.2);
}

.intake-btn-primary:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(32, 36, 54, 0.3);
  opacity: 0.95;
}

.intake-btn-outline {
  background: white;
  color: var(--intake-void);
  border: 1.5px solid var(--intake-border);
  padding: 12px 28px;
  border-radius: 10px;
  font-weight: 600;
  font-size: 14px;
  transition: all 0.25s ease;
}

.intake-btn-outline:hover {
  border-color: var(--intake-aqua);
  background: var(--intake-aqua-light);
}

.intake-pill {
  padding: 8px 18px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 500;
  border: 1.5px solid var(--intake-border);
  background: white;
  color: #4a4d5e;
  transition: all 0.2s ease;
  cursor: pointer;
}

.intake-pill:hover {
  border-color: var(--intake-aqua);
  background: var(--intake-aqua-light);
}

.intake-pill-selected {
  background: var(--intake-aqua);
  border-color: var(--intake-aqua);
  color: var(--intake-void);
  font-weight: 600;
  box-shadow: 0 1px 4px rgba(190, 214, 209, 0.4);
}

.intake-completion {
  background: linear-gradient(135deg, white 0%, var(--intake-aqua-light) 100%);
  border-radius: 20px;
  padding: 60px 40px;
  text-align: center;
  border: 1px solid var(--intake-border);
  position: relative;
  overflow: hidden;
}

.intake-completion::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, var(--intake-aqua), var(--intake-sand), var(--intake-aqua));
}

.intake-completion-icon {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--intake-aqua) 0%, #a8ccc5 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 24px;
  box-shadow: 0 4px 20px rgba(190, 214, 209, 0.5);
}

.intake-stage-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  transition: all 0.3s ease;
}

.intake-stage-dot-active {
  background: var(--intake-aqua);
  box-shadow: 0 0 0 3px rgba(190, 214, 209, 0.3);
}

.intake-stage-dot-inactive {
  background: rgba(255, 255, 255, 0.3);
}

.intake-stage-dot-completed {
  background: var(--intake-aqua);
}

.intake-radio-group label {
  transition: color 0.2s ease;
}

.intake-radio-group label:hover {
  color: var(--intake-void);
}

.intake-input-focus:focus-within {
  border-color: var(--intake-aqua);
  box-shadow: 0 0 0 3px rgba(190, 214, 209, 0.2);
}

